import{_ as a,o,c as t,a3 as i}from"./chunks/framework.rPoJfhSN.js";const m=JSON.parse('{"title":"VPS frente a hosting compartido","description":"","frontmatter":{},"headers":[],"relativePath":"operacion/vps-vs-hosting-compartido.md","filePath":"operacion/vps-vs-hosting-compartido.md","lastUpdated":1786330671000}'),r={name:"operacion/vps-vs-hosting-compartido.md"};function s(d,e,n,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="vps-frente-a-hosting-compartido" tabindex="-1">VPS frente a hosting compartido <a class="header-anchor" href="#vps-frente-a-hosting-compartido" aria-label="Permalink to &quot;VPS frente a hosting compartido&quot;">​</a></h1><p>Plazora recomienda una VPS Ubuntu Server con Nginx administrada por el propietario. El hosting compartido se incluye en esta comparación para explicar las diferencias, no como arquitectura objetivo.</p><h2 id="comparativa-rapida" tabindex="-1">Comparativa rápida <a class="header-anchor" href="#comparativa-rapida" aria-label="Permalink to &quot;Comparativa rápida&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capacidad</th><th>VPS administrada por ti</th><th>Hosting compartido</th></tr></thead><tbody><tr><td>PHP 8.5 y extensiones</td><td>Controlas versión y módulos</td><td>Depende del proveedor</td></tr><tr><td>Nginx y reglas HTTP</td><td>Configuración completa</td><td>Limitada o inexistente</td></tr><tr><td>Workers de colas</td><td>Procesos permanentes con Supervisor/systemd</td><td>Frecuentemente no permitidos</td></tr><tr><td>Scheduler</td><td>Cron cada minuto bajo tu control</td><td>Cron limitado por plan</td></tr><tr><td>Deploy con Git</td><td>Flujo completo, deploy keys y releases</td><td>Puede estar restringido</td></tr><tr><td>Acceso SSH</td><td>Completo y administrable</td><td>Parcial, compartido o no disponible</td></tr><tr><td>MySQL</td><td>Ajustes, usuarios y backups controlados</td><td>Recursos y configuración compartidos</td></tr><tr><td>Backups</td><td>Política, cifrado y restauración propios</td><td>Dependencia del proveedor</td></tr><tr><td>Observabilidad</td><td>Logs, métricas y alertas completas</td><td>Visibilidad limitada</td></tr><tr><td>Seguridad del servidor</td><td>Responsabilidad y control propios</td><td>Parcialmente delegada</td></tr><tr><td>Escalamiento</td><td>Puedes aumentar recursos o separar servicios</td><td>Limitado al catálogo de planes</td></tr><tr><td>Costo inicial</td><td>Mayor que un hosting básico</td><td>Generalmente menor</td></tr><tr><td>Conocimiento requerido</td><td>Administración de Linux y servicios</td><td>Menor carga operativa</td></tr></tbody></table><h2 id="vps-ubuntu-server-con-nginx" tabindex="-1">VPS Ubuntu Server con Nginx <a class="header-anchor" href="#vps-ubuntu-server-con-nginx" aria-label="Permalink to &quot;VPS Ubuntu Server con Nginx&quot;">​</a></h2><h3 id="ventajas" tabindex="-1">Ventajas <a class="header-anchor" href="#ventajas" aria-label="Permalink to &quot;Ventajas&quot;">​</a></h3><ul><li>Control exacto de PHP 8.5, Nginx, MySQL, Composer y Node.js.</li><li>Workers permanentes para correos, pagos y tareas asíncronas.</li><li>Deploys reproducibles desde el repositorio privado.</li><li>Backups, firewall, TLS, monitoreo y políticas de acceso definidos por ti.</li><li>Mejor capacidad para investigar rendimiento y ajustar recursos.</li><li>Posibilidad de crecer hacia Redis, almacenamiento externo, CDN o servicios separados.</li></ul><h3 id="desventajas" tabindex="-1">Desventajas <a class="header-anchor" href="#desventajas" aria-label="Permalink to &quot;Desventajas&quot;">​</a></h3><ul><li>Requiere administrar parches, firewall, SSH, certificados, procesos y backups.</li><li>Una mala configuración puede introducir riesgos de seguridad o disponibilidad.</li><li>Necesita monitoreo y una rutina operativa; no es un servicio que se deba abandonar después de instalar.</li></ul><h2 id="hosting-compartido" tabindex="-1">Hosting compartido <a class="header-anchor" href="#hosting-compartido" aria-label="Permalink to &quot;Hosting compartido&quot;">​</a></h2><h3 id="ventajas-1" tabindex="-1">Ventajas <a class="header-anchor" href="#ventajas-1" aria-label="Permalink to &quot;Ventajas&quot;">​</a></h3><ul><li>Menor precio de entrada.</li><li>Panel gráfico y mantenimiento básico del servidor gestionado por un tercero.</li><li>Puede servir para una demostración temporal si ofrece PHP 8.5 y satisface todos los requisitos.</li></ul><h3 id="desventajas-1" tabindex="-1">Desventajas <a class="header-anchor" href="#desventajas-1" aria-label="Permalink to &quot;Desventajas&quot;">​</a></h3><ul><li>No garantiza control sobre PHP 8.5, extensiones ni configuración de procesos.</li><li>Puede impedir workers persistentes, cron por minuto, comandos SSH o enlaces simbólicos.</li><li>Los recursos se comparten con otros clientes y el rendimiento es menos predecible.</li><li>Los deploys, logs, backups y recuperación suelen estar sujetos a las herramientas del proveedor.</li><li>Las restricciones pueden romper pagos, colas, generación de assets o tareas programadas aunque la página inicial cargue.</li></ul><div class="warning custom-block"><p class="custom-block-title">No recomendado para producción</p><p>Que un hosting compartido consiga mostrar la página de inicio no significa que pueda operar correctamente todo el marketplace. Plazora necesita control de colas, scheduler, almacenamiento, permisos, callbacks de pago y procesos de despliegue; por ello la referencia soportada es una VPS Ubuntu Server con Nginx.</p></div><h2 id="responsabilidad-operativa" tabindex="-1">Responsabilidad operativa <a class="header-anchor" href="#responsabilidad-operativa" aria-label="Permalink to &quot;Responsabilidad operativa&quot;">​</a></h2><p>Elegir una VPS cambia dependencia por control. El propietario debe mantener:</p><ol><li>Actualizaciones de seguridad de Ubuntu y paquetes.</li><li>Acceso SSH mediante llaves, usuarios sin privilegios y firewall.</li><li>Nginx, PHP-FPM, MySQL, workers y cron saludables.</li><li>TLS renovable automáticamente.</li><li>Backups cifrados con restauraciones probadas.</li><li>Monitoreo de errores, recursos, disco, colas y pagos.</li><li>Un procedimiento de release y rollback basado en Git.</li></ol><p>La <a href="/docs/operacion/despliegue-vps.html">guía de despliegue en VPS</a> contiene la configuración de referencia.</p>',19)])])}const h=a(r,[["render",s]]);export{m as __pageData,h as default};
